// ─── File: src/main/java/com/bank/connectarch/demo/ConnectArchitectureDemo.java ───
// Models Connectors (plan), Tasks (move), Workers (host), Converters (format),
// and standalone vs distributed assignment with worker-failure reassignment.
package com.bank.connectarch.demo;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ConnectArchitectureDemo {

    private static final Logger log = Logger.getLogger("ConnectArch");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Converter converter = new Converter("Avro");

        // Connector plans the work: 3 tables + 3 partitions → up to 6 tasks.
        Connector connector = new Connector("accounts-source", 6, converter);
        List<Task> tasks = connector.plan();

        log.info("=== STANDALONE mode: one worker hosts all tasks (dev) ===");
        ConnectCluster standalone = new ConnectCluster(1);
        standalone.assign(tasks);
        standalone.runAll();

        log.info("=== DISTRIBUTED mode: 3 workers, tasks balanced (production) ===");
        ConnectCluster distributed = new ConnectCluster(3);
        distributed.assign(tasks);
        distributed.report();

        log.info("=== worker-1 crashes: its tasks are reassigned (fault tolerance) ===");
        distributed.killWorker(1);
        distributed.report();
    }
}

// ─── Would be in Converter.java (serialize/deserialize format) ───
class Converter {
    private final String format;
    Converter(String format) { this.format = format; }
    String serialize(String record) { return "[" + format + "]" + record; }
    String format() { return format; }
}

// ─── Would be in Task.java (actually moves data) ───
class Task {
    final String id; private final Converter converter;
        Task(String id, Converter converter) { this.id = id;
        this.converter = converter; }
    void move(String record) {
        // the only component that touches bytes, via the converter
        converter.serialize(record);
    }
}

// ─── Would be in Connector.java (defines WHAT to connect, plans tasks) ───
class Connector {
    private static final Logger log = Logger.getLogger("ConnectArch");
    private final String name; private final int maxTasks; private final Converter converter;
    Connector(String name, int maxTasks, Converter converter) {
            this.name = name;
            this.maxTasks = maxTasks
            this.converter = converter;
    }
    List<Task> plan() {
        // Connector does NO data movement; it only divides the job into tasks.
        List<Task> tasks = new ArrayList<>();
        for (int i = 0; i < maxTasks; i++) tasks.add(new Task(name + "-task-" + i, converter));
        log.info(() -> "connector " + name + " planned " + tasks.size()
                + " tasks (converter=" + converter.format() + ")");
        return tasks;
    }
}

// ─── Would be in Worker.java (JVM process hosting tasks) ───
class Worker {
    private static final Logger log = Logger.getLogger("ConnectArch");
    final int id; private final List<Task> hosted = new ArrayList<>();
    Worker(int id) { this.id = id; }
    void host(Task t) { hosted.add(t); }
    void clear() { hosted.clear(); }
    List<Task> tasks() { return hosted; }
    void run() {
        for (Task t : hosted) t.move("row");
        log.info(() -> "worker-" + id + " running " + hosted.size() + " task(s)");
    }
}

// ─── Would be in ConnectCluster.java (assigns tasks to workers, rebalances) ───
class ConnectCluster {
    private static final Logger log = Logger.getLogger("ConnectArch");
    private final List<Worker> workers = new ArrayList<>();
    private List<Task> allTasks = new ArrayList<>();
    ConnectCluster(int workerCount) {
        for (int i = 0; i < workerCount; i++) workers.add(new Worker(i));
    }
    void assign(List<Task> tasks) {
        this.allTasks = tasks;
        rebalance();
    }
    private void rebalance() {
        for (Worker w : workers) w.clear();
        List<Worker> alive = new ArrayList<>();
        for (Worker w : workers) if (w != null) alive.add(w);
        for (int i = 0; i < allTasks.size(); i++) {
            alive.get(i % alive.size()).host(allTasks.get(i));  // even spread
        }
    }
    void killWorker(int id) {
        workers.removeIf(w -> w.id == id);
        log.severe(() -> "worker-" + id + " died; rebalancing tasks to survivors");
        rebalance();   // distributed mode reassigns from Kafka-stored assignments
    }
    void runAll() { for (Worker w : workers) w.run(); }
    void report() {
        for (Worker w : workers) {
            List<String> ids = new ArrayList<>();
            for (Task t : w.tasks()) ids.add(t.id);
            log.info(() -> "worker-" + w.id + " owns " + ids);
        }
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
